#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker was a raw UObject pointer without UPROPERTY, so the garbage collector (first run ~60s into play) freed the UArenaScoreTracker; OnGoalScored then called AddPoints on a dangling pointer -> EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints. Fixed by making it UPROPERTY() TObjectPtr.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is only loaded by string path via LoadObject, so the cooker never saw a hard reference and did not package it (only /Game/Maps/Arena and /Game/Data/Effects are cooked). In the packaged build LoadObject returns null and the HUD falls back to gray. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook."
}
